import { unit } from 'mathjs';

const span  = unit(3, 'km');
const gap   = unit(500, 'm');
const total = span.add(gap);                 // Unit 3.5 km
total.toNumber('m');                         // 3500
unit('60 mile/hour').to('km/h');             // 96.56064 km/h
span.add(unit(2, 's'));                      // throws: units do not match

