import { unit } from 'mathjs';

const span  = unit(3, 'km');
const gap   = unit(500, 'm');
const total = span.add(gap);                 // Unit 3.5 km
total.toNumber('m');                         // 3500
unit('60 mile/hour').to('km/h');             // 96.56064 km/h
span.add(unit(2, 's'));                      // throws: units do not match

const FACTORS = { m: 1, km: 1e3, ft: 0.3048 };          // one table, one dimension
const q = (value, unit) => Object.freeze({ value, unit });
const to = ({ value, unit }, target) =>
  q((value * FACTORS[unit]) / FACTORS[target], target);
const add = (a, b) => q(a.value + to(b, a.unit).value, a.unit);
// add(q(3, 'km'), q(500, 'm')) -> { value: 3.5, unit: 'km' }
